/**
 * Filter by repository URL.
 */
repository?: string;
/**
 * Filter by stable benchmark identifier.
 */
benchmark_id?: string;
/**
 * Latest commit at or after this instant, RFC3339.
 */
active_since?: string;
/**
 * Latest commit at or before this instant, RFC3339.
 */
active_until?: string;
/**
 * Pagination cursor from a previous page.
 */
cursor?: string;
/**
 * Page size (max 1000).
 */
